const tlRolled = (P, x, y, s, lw = 0.6) => {
  const w = 11 * s, hh = 6 * s;
  P.shape([[x - w, y - hh], [x + w, y - hh], [x + w, y + hh], [x - w, y + hh]], 'y1', lw);
  for (let i = 0; i < 3; i++) P.line([[x - w * 0.6, y - hh * 0.45 + i * hh * 0.45], [x + w * 0.6, y - hh * 0.45 + i * hh * 0.45]], lw * 0.6);
  for (const e of [-1, 1]) { P.shape([[x + e * w - 3 * s, y - hh - 3 * s], [x + e * w + 3 * s, y - hh - 3 * s], [x + e * w + 3 * s, y + hh + 3 * s], [x + e * w - 3 * s, y + hh + 3 * s]], 'y3r2k1', lw); P.line([[x + e * w, y - hh - 8 * s], [x + e * w, y + hh + 8 * s]], 1.6 * s, { ink: 3, lvl: 8, taper: 0 }); }
};
Object.assign(PROPS2, {
  /* tablette de cire tenue devant soi, stylet dans l'autre main */
  tlTablet(P, A, J, M, h, t, lw, F) {
    const c = M([(J.aN.t[0] + J.aF.t[0]) / 2, (J.aN.t[1] + J.aF.t[1]) / 2 + 0.01]), s = h / 140, fc = F.face || 1;
    P.shape([[c[0] - 13 * s, c[1] - 2 * s], [c[0] + 13 * s, c[1] - 6 * s], [c[0] + 13 * s, c[1] + 3 * s], [c[0] - 13 * s, c[1] + 7 * s]], 'r5y5k2', lw * 0.6);
    P.fill([[c[0] - 10 * s, c[1] - 1 * s], [c[0] + 10 * s, c[1] - 4.5 * s], [c[0] + 10 * s, c[1] + 1.5 * s], [c[0] - 10 * s, c[1] + 5 * s]], 'y6r3k2', {});
    for (let i = 0; i < 2; i++) P.line([[c[0] - 8 * s, c[1] + (0.5 + i * 2.4) * s], [c[0] + 7 * s, c[1] + (-2.2 + i * 2.4) * s]], lw * 0.35);
    const q = M(J.aN.t); P.line([[q[0], q[1] + 2 * s], [q[0] + fc * 6 * s, q[1] - 10 * s]], lw * 1.1, { ink: 3, lvl: 7, taper: 0 });
  },
  /* la règle de bâtisseur de Chammaï */
  tlCubit(P, A, J, M, h, t, lw, F, u, n, add) {
    const a = add(A.w, [0, 1], 0.1), b = add(A.w, [0, -1], 0.38), q0 = M(a), q1 = M(b), s = h / 140;
    P.shape([[q0[0] - 2.6 * s, q0[1]], [q0[0] + 2.6 * s, q0[1]], [q1[0] + 2.6 * s, q1[1]], [q1[0] - 2.6 * s, q1[1]]], 'r4y6k2', lw * 0.7);
    for (let i = 1; i < 7; i++) { const y = lerp(q0[1], q1[1], i / 7); P.line([[q0[0] - 2.6 * s, y], [q0[0] + (i % 2 ? 0 : 2) * s, y]], lw * 0.5); }
  },
  /* le rouleau roulé, tenu dans les deux mains */
  tlRoll(P, A, J, M, h, t, lw) { const c = M([(J.aN.t[0] + J.aF.t[0]) / 2, (J.aN.t[1] + J.aF.t[1]) / 2 - 0.01]); tlRolled(P, c[0], c[1], h / 150, lw * 0.6); },
  /* le gros volume fermé, levé à deux mains (le siyoum) */
  tlVolume(P, A, J, M, h, t, lw) {
    const c = M([(J.aN.t[0] + J.aF.t[0]) / 2, (J.aN.t[1] + J.aF.t[1]) / 2 - 0.06]), s = h / 140;
    P.shape([[c[0] - 15 * s, c[1] - 20 * s], [c[0] + 15 * s, c[1] - 22 * s], [c[0] + 15 * s, c[1] + 18 * s], [c[0] - 15 * s, c[1] + 20 * s]], 'r7b3k3', lw * 0.8);
    P.shape([[c[0] + 15 * s, c[1] - 22 * s], [c[0] + 19 * s, c[1] - 20 * s], [c[0] + 19 * s, c[1] + 20 * s], [c[0] + 15 * s, c[1] + 18 * s]], 'y1', lw * 0.6);
    P.line([[c[0] - 11 * s, c[1] - 14 * s], [c[0] + 11 * s, c[1] - 15 * s], [c[0] + 11 * s, c[1] + 12 * s], [c[0] - 11 * s, c[1] + 13 * s], [c[0] - 11 * s, c[1] - 14 * s]], lw * 0.8, { ink: 0, lvl: 9, taper: 0 });
    P.fill([[c[0] - 6 * s, c[1] - 6 * s], [c[0] + 6 * s, c[1] - 7 * s], [c[0] + 6 * s, c[1] - 1 * s], [c[0] - 6 * s, c[1]]], 'y8r2', {});
    P.halo(c[0], c[1], 40 * s, ['y1', 'y2'], {});
  },
  tlBook(P, A, J, M, h, t, lw) {
    const c = [(J.aN.t[0] + J.aF.t[0]) / 2, (J.aN.t[1] + J.aF.t[1]) / 2 - 0.02], q = M(c), w = h * 0.07, e = h * 0.05;
    P.shape([[q[0] - w - 2, q[1] - e * 0.4], [q[0], q[1] - e * 0.1], [q[0] + w + 2, q[1] - e * 0.4], [q[0] + w + 2, q[1] + e * 0.8], [q[0], q[1] + e * 1.1], [q[0] - w - 2, q[1] + e * 0.8]], 'r6b3k2', lw * 0.7);
    for (const s of [-1, 1]) { P.shape([[q[0], q[1] - e * 0.3], [q[0] + s * w, q[1] - e * 0.6], [q[0] + s * w, q[1] + e * 0.6], [q[0], q[1] + e * 0.85]], 'y1', lw * 0.6); for (let i = 0; i < 4; i++) P.line([[q[0] + s * w * 0.2, q[1] - e * 0.25 + i * e * 0.25], [q[0] + s * w * 0.85, q[1] - e * 0.45 + i * e * 0.25]], lw * 0.3); }
  }
});
