    for (const k of [2, 4, 7, 9, 12, 14]) tlPalmFar(P, hz[k][0], hz[k][1] + 6, 1.1 + (k % 3) * 0.15);
    { const q = hz[10]; P.shape([[q[0] - 26, q[1] + 8], [q[0] - 16, q[1] - 22], [q[0] + 16, q[1] - 22], [q[0] + 26, q[1] + 8]], 'y5r3k2', 0.7); P.shape([[q[0] - 12, q[1] - 22], [q[0] - 8, q[1] - 40], [q[0] + 8, q[1] - 40], [q[0] + 12, q[1] - 22]], 'y5r3k2', 0.6); }
    Lib.platform(P, 'y5r3k1', 'y4r3k2', { h: 50 });
    P.fill([P.I(0, 0, 0.3), P.I(540, 540, 0.3), P.I(0, 540, 0.3)], 'y4b4k1', {});
    Lib.grass(P, 34, 'y5b4', [20, 250, 220, 280]);
    for (let i = 0; i < 14; i++) { const u = 30 + i * 36, c = P.I(u, u, 0); P.shape(Lib.bumpy(P, c[0], c[1] - 3, 7, 4, 5), 'y3r2k3', 0.6); }
